"""Detection rules for the TPL watcher (generated by the private repo's build script — do not edit by hand).

Standard library only. Classifies football news headlines: Romano "Here we go" · Romano exit report · club official.
"""
from __future__ import annotations

import hashlib
import html
import re
import unicodedata
import urllib.request
import xml.etree.ElementTree as ET
from datetime import datetime, timedelta, timezone
from email.utils import parsedate_to_datetime

KST = timezone(timedelta(hours=9))


UA = "Mozilla/5.0 (compatible; tpl-transfer-check/1.0)"


HWG = re.compile(r"here\s*we\s*go", re.I)


HWG_NOT = re.compile(r"\b(close\s+to|almost|nearly|imminent|expected|awaiting|waiting\s+for|then|before|no|not\s+(yet\s+)?(a\s+)?)"
                     r"\s*['\"‘“]?\s*here\s*we\s*go"
                     r"|here\s*we\s*go['\"’”!]*\s*(soon|imminent|expected|coming|could|is\s+close|edging|not\s+yet|yet|to\s+follow)", re.I)


ROMANO = re.compile(r"\bromano\b|로마노", re.I)


SACK = re.compile(r"\b(sack(s|ed)?|fire[sd]|dismiss(es|ed)|part(s|ed)?\s+(company|ways)|relieved\s+of\s+(his\s+|her\s+)?duties"
                  r"|resign(s|ed)?|steps?\s+down|stepped\s+down|leaves?\s+[\w .'’-]{0,40}with\s+immediate\s+effect|axe[sd])\b", re.I)


APPOINT = re.compile(r"\b(appoint(s|ed)?|named\s+(as\s+)?(the\s+)?(new\s+)?(head\s+coach|manager|boss)|new\s+(head\s+coach|manager|boss)"
                     r"|confirm(s|ed)?\s+[\w .'’-]{0,40}\s+as\s+(new\s+)?(head\s+coach|manager|boss))\b", re.I)


RENEW = re.compile(r"\b(sign(s|ed)?\s+(a\s+)?new\s+([\w-]+\s+){0,2}(contract|deal)|extend(s|ed)?\s+(his\s+|her\s+)?(contract|deal|stay)"
                   r"|contract\s+(extension|renewal)|renew(s|ed)?)\b", re.I)


COMPLETE = re.compile(
    r"\b(complete[sd]?|seal(s|ed)?|finali[sz]e[sd]?|wrap(s|ped)?\s+up)\s+(his\s+|her\s+|a\s+|the\s+)?"
    r"([\w£€$.]+\s+){0,3}(move|transfer|switch|signing|deal|loan)\b"
    r"|\bconfirm(s|ed)?\s+(the\s+)?([\w'’-]+\s+){0,3}(signing|arrival|capture|transfer|loan|departure|sale)\b"
    r"|\b(officially\s+)?(signs|signed)\s+(for|with)\b"
    r"|\b(has\s+)?(officially\s+)?joined\b|\bofficially\s+joins?\b"
    r"|\bunveil(s|ed)?\b|\bofficial\s*[:!]"
    r"|\bjoins?\s+[\w .'’-]{2,40}\s+(on\s+(a\s+)?(loan|free|permanent|season-long)|for\s+[£€$]|from\s+[A-Z])", re.I)


RUMOUR = re.compile(r"\b(set\s+to|moves?\s+to|making\s+moves|close\s+to|closing\s+in|nearing|near(s)?\s+(a\s+)?(move|deal)|on\s+the\s+verge|on\s+the\s+brink|poised|"
                    r"in\s+talks|talks|negotiat\w*|bid|offer(s|ed)?|target(s|ed|ing)?|interest(ed)?|eye(s|ing)?|keen|could|would|may|might|"
                    r"consider(s|ing)?|monitor(s|ing)?|linked|rumou?r(s|ed)?|reportedly|reports?|claim(s|ed)?|expected|edge(s)?\s+closer|"
                    r"agree(s|d)?\s+(personal\s+)?terms|in\s+principle|verbal(ly)?|plan(s|ning)?|want(s|ed)?|approach(es|ed)?|"
                    r"enquir(y|ies)|race|battle|chase|pursuit|tracking|scout(s|ing|ed)?|facing|face\s+the|under\s+pressure|"
                    r"ultimatum|future\s+in\s+doubt|if|why|how|what|whether|favourite|frontrunner|shortlist|candidate|"
                    r"won'?t|will\s+not|not\s+be|denies|deny)\b|\?", re.I)


CLAUSE = re.compile(r"\s+(?:with|as|amid|after|while|and|but|following)\s+|[,;:|–—]\s*|\s-\s")


def now_kst() -> datetime:
    return datetime.now(KST)


def _hm(s: str) -> tuple[int, int]:
    h, m = s.split(":")
    return int(h), int(m)


def in_window(t: datetime, conf: dict) -> bool:
    """15:00 ~ 03:00(+grace 분) 사이인가(GitHub 예약 지연 대비 grace)."""
    sh, sm = _hm(conf.get("window_start", "15:00"))
    eh, em = _hm(conf.get("window_end", "03:00"))
    mins = t.hour * 60 + t.minute
    return mins >= sh * 60 + sm or mins <= eh * 60 + em + int(conf.get("grace_min", 60))


def window_day(t: datetime, conf: dict | None = None) -> str:
    """하루 한도를 세는 날짜 — 자정~오후 시작 전은 전날 회차."""
    sh, _ = _hm((conf or {}).get("window_start", "15:00"))
    return (t - timedelta(days=1) if t.hour < sh else t).strftime("%Y-%m-%d")


def fetch(url: str, timeout: int = 20) -> str:
    req = urllib.request.Request(url, headers={"User-Agent": UA, "Accept": "application/rss+xml, application/xml, text/xml"})
    with urllib.request.urlopen(req, timeout=timeout) as r:
        return r.read().decode("utf-8", errors="replace")


def _text(el, tag: str) -> str:
    x = el.find(tag)
    return (x.text or "").strip() if x is not None and x.text else ""


def strip_html(s: str) -> str:
    return re.sub(r"\s+", " ", html.unescape(re.sub(r"<[^>]+>", " ", s or ""))).strip()


def parse_rss(xml_text: str, feed: dict) -> list[dict]:
    try:
        root = ET.fromstring(xml_text)
    except ET.ParseError:
        return []
    out = []
    for it in root.iter("item"):
        title = strip_html(_text(it, "title"))
        link = _text(it, "link")
        if not title or not link:
            continue
        publisher = feed.get("outlet", "")
        if feed.get("aggregator"):
            src = it.find("source")
            if src is not None and (src.text or "").strip():
                publisher = src.text.strip()
            m = re.search(r"\s+[-–|]\s+([^-–|]{2,60})$", title)
            if m:
                publisher = publisher or m.group(1).strip()
                title = title[:m.start()].strip()
        summary = strip_html(_text(it, "description"))
        if norm(summary).startswith(norm(title)[:40]):
            summary = ""                                  # 구글 뉴스 요약은 제목 반복 — 버림
        try:
            pub = parsedate_to_datetime(_text(it, "pubDate")).astimezone(timezone.utc).isoformat()
        except (TypeError, ValueError, IndexError):
            pub = ""
        out.append({"id": item_id(link, title), "title": title, "summary": summary[:400], "link": link,
                    "publisher": publisher or feed.get("name", ""), "published": pub, "feed": feed.get("name", "")})
    return out


def item_id(link: str, title: str) -> str:
    return hashlib.sha1(f"{link}|{norm(title)}".encode("utf-8")).hexdigest()[:16]


def norm(s: str) -> str:
    s = unicodedata.normalize("NFKD", s or "")
    s = "".join(c for c in s if not unicodedata.combining(c))
    return re.sub(r"[^0-9a-z가-힣]+", " ", s.lower()).strip()


def contains(text: str, name: str) -> bool:
    """단어 단위 포함(대소문자·악센트 무시)."""
    n, t = norm(name), norm(text)
    return bool(n) and re.search(rf"(^| ){re.escape(n)}( |$)", t) is not None


def big_clubs_in(text: str, conf: dict) -> list[str]:
    """글에 나오는 빅클럽 key(나온 순서 무관, 중복 없음)."""
    out = []
    for c in conf.get("big_clubs", []):
        t = f" {norm(text)} "
        for bad in c.get("not_names", []):              # 'Inter Miami' 는 인테르가 아님, 'Inter Milan' 의 Milan 은 AC 밀란이 아님
            t = t.replace(f" {norm(bad)} ", " | ")
        if any(contains(t, n) for n in c.get("names", [])):
            out.append(c["key"])
    return out


def clauses(title: str) -> list[str]:
    return [c for c in CLAUSE.split(title or "") if c and c.strip()]


def is_hwg(title: str, summary: str = "") -> bool:
    text = f"{title} {summary}"
    return bool(HWG.search(text) and ROMANO.search(text) and not HWG_NOT.search(text))


def is_romano_exit(title: str, summary: str = "") -> bool:
    """로마노의 경질·사임 확정 보도(예정·압박·가능성 표현은 아님)."""
    text = f"{title} {summary}"
    if not ROMANO.search(text):
        return False
    return any(SACK.search(c) and not RUMOUR.search(c) for c in clauses(title))


def official_event(title: str) -> str:
    """공식 발표 뒤의 기사로 보이면 사건 종류(transfer · appointment · sacking · renewal), 아니면 ''.
    문장을 쪼개 그 동사가 있는 부분에 루머·예정 표현이 없어야 함('sack X with Y set to be appointed' → sacking)."""
    for c in clauses(title):
        if RUMOUR.search(c):
            continue
        if SACK.search(c):
            return "sacking"
        if APPOINT.search(c):
            return "appointment"
        if RENEW.search(c):
            return "renewal"
        if COMPLETE.search(c):
            return "transfer"
    return ""


def classify(item: dict) -> str:
    title, summary = item.get("title", ""), item.get("summary", "")
    if is_hwg(title, summary):
        return "hwg"
    if is_romano_exit(title, summary):
        return "romano"
    if official_event(title):
        return "official"
    return ""


def fresh(item: dict, now: datetime, hours: float) -> bool:
    if not item.get("published"):
        return True
    try:
        return now - datetime.fromisoformat(item["published"]) <= timedelta(hours=hours)
    except ValueError:
        return True


def relevant(items: list[dict], conf: dict, now: datetime | None = None) -> list[dict]:
    """빅클럽 관련 + hwg/romano/official 로 분류되는 최근 기사."""
    now = now or now_kst()
    out = []
    for it in items:
        k = classify(it)
        clubs = big_clubs_in(f"{it.get('title', '')} {it.get('summary', '')}", conf)
        if k and clubs and fresh(it, now, float(conf.get("fresh_hours", 14))):
            out.append({**it, "kind": k, "clubs": clubs})
    return out
